        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateYaml, type ValidationResult } from \"./yaml-validator\";\n\ndescribe(\"yaml-validator\", () => {\n  describe(\"valid YAML\", () => {\n    test(\"simple key-value mapping\", () => {\n      const result = validateYaml(\"name: Alice\\nage: 30\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"nested mappings with proper indentation\", () => {\n      const yaml = [\n        \"person:\",\n        \"  name: Alice\",\n        \"  address:\",\n        \"    city: Wonderland\",\n        \"    zip: 12345\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"sequences with dash-space prefix\", () => {\n      const yaml = [\n        \"fruits:\",\n        \"  - apple\",\n        \"  - banana\",\n        \"  - cherry\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"mixed mappings and sequences\", () => {\n      const yaml = [\n        \"people:\",\n        \"  - name: Alice\",\n        \"    age: 30\",\n        \"  - name: Bob\",\n        \"    age: 25\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"double-quoted strings\", () => {\n      const result = validateYaml('message: \"Hello, World!\"');\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"single-quoted strings\", () => {\n      const result = validateYaml(\"message: 'Hello, World!'\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"double-quoted string with escapes\", () => {\n      const result = validateYaml('message: \"line1\\\\nline2\"');\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"multi-line block scalar with literal style (|)\", () => {\n      const yaml = [\n        \"description: |\",\n        \"  This is a long\",\n        \"  description that spans\",\n        \"  multiple lines.\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"multi-line block scalar with folded style (>)\", () => {\n      const yaml = [\n        \"description: >\",\n        \"  This is a long\",\n        \"  description that will\",\n        \"  be folded.\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"block scalar with strip chomp indicator (|-)\", () => {\n      const yaml = [\n        \"text: |-\",\n        \"  stripped trailing\",\n        \"  newlines here\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"block scalar with keep chomp indicator (|+)\", () => {\n      const yaml = [\n        \"text: |+\",\n        \"  keep trailing\",\n        \"  newlines here\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"block scalar with folded-strip (>-)\", () => {\n      const yaml = [\n        \"text: >-\",\n        \"  folded and stripped\",\n        \"  content here\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"block scalar with folded-keep (>+)\", () => {\n      const yaml = [\n        \"text: >+\",\n        \"  folded and kept\",\n        \"  content here\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"full-line comments\", () => {\n      const yaml = [\n        \"# This is a comment\",\n        \"name: Alice\",\n        \"# Another comment\",\n        \"age: 30\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"inline comments\", () => {\n      const result = validateYaml(\"name: Alice # a comment\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"empty content\", () => {\n      const result = validateYaml(\"\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"whitespace-only content\", () => {\n      const result = validateYaml(\"   \\n  \\n   \");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"document start marker (---)\", () => {\n      const yaml = [\"---\", \"name: Alice\", \"age: 30\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"document end marker (...)\", () => {\n      const yaml = [\"name: Alice\", \"...\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"flow mapping\", () => {\n      const result = validateYaml(\"{key: value}\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"flow mapping with multiple entries\", () => {\n      const result = validateYaml(\"{a: 1, b: 2}\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"flow sequence\", () => {\n      const result = validateYaml(\"[1, 2, 3]\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"flow collection as mapping value\", () => {\n      const result = validateYaml(\"items: [apple, banana, cherry]\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"nested flow collection as mapping value\", () => {\n      const result = validateYaml(\"config: {debug: true, ports: [80, 443]}\");\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"boolean scalar values\", () => {\n      const yaml = [\"enabled: true\", \"disabled: false\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"null scalar values\", () => {\n      const yaml = [\"empty: null\", \"also_empty: ~\"].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"numeric scalar values\", () => {\n      const yaml = [\n        \"integer: 42\",\n        \"negative: -7\",\n        \"float: 3.14\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"mapping with empty value\", () => {\n      const yaml = [\n        \"parent:\",\n        \"  child: value\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"empty lines between entries\", () => {\n      const yaml = [\n        \"name: Alice\",\n        \"\",\n        \"age: 30\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n\n    test(\"sequence item with block scalar\", () => {\n      const yaml = [\n        \"items:\",\n        \"  - |\",\n        \"    multi line\",\n        \"    content\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(true);\n      expect(result.errors).toEqual([]);\n    });\n  });\n\n  describe(\"invalid YAML\", () => {\n    test(\"tab indentation\", () => {\n      const yaml = \"name:\\n\\tvalue\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"Tab\");\n    });\n\n    test(\"tab indentation reports correct line number\", () => {\n      const yaml = \"name: ok\\n\\tbad: line\";\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors[0].line).toBe(2);\n    });\n\n    test(\"inconsistent de-indentation\", () => {\n      const yaml = [\n        \"root:\",\n        \"    deep:\",\n        \"      deeper: value\",\n        \"   bad: indentation\",\n      ].join(\"\\n\");\n      const result = validateYaml(yaml);\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"de-indentation\");\n    });\n\n    test(\"missing colon-space separator in mapping\", () => {\n      const result = validateYaml(\"key:value\");\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"colon\");\n    });\n\n    test(\"unmatched double quote\", () => {\n      const result = validateYaml('name: \"unclosed');\n      expect(result.valid).toBe(false);\n      expect(result.errors.length).toBeGreaterThan(0);\n      expect(result.errors[0].message).toContain(\"quote\");\n    });\n\n    test(\"unmatched single quote\", () => {\n      const