async function testBunFileAPI() {
  // Create a test file
  const testPath = "/tmp/hypothesis-add/test-file.txt";
  await Bun.write(testPath, "hello world");

  // Test Bun.file() returns an object
  const file = Bun.file(testPath);
  console.log("typeof Bun.file():", typeof file);
  console.log("Bun.file() constructor:", file.constructor.name);

  // Test exists() method
  const existsResult = file.exists();
  console.log("typeof exists():", typeof existsResult);
  console.log("exists() is Promise:", existsResult instanceof Promise);
  const existsValue = await existsResult;
  console.log("exists() resolved value:", existsValue);
  console.log("exists() resolved type:", typeof existsValue);

  // Test text() method
  const textResult = file.text();
