/**
 * CLI entry point for YAML syntax validation.
 * Accepts a file path argument, validates the YAML content,
 * and reports results with appropriate exit codes.
 */

import { validateYaml } from "./yaml-validator";

const filePath = process.argv[2];

if (!filePath) {
  console.error("Usage: bun run validate <filepath>");
  process.exit(1);
}

const file = Bun.file(filePath);
const exists = await file.exists();

if (!exists) {
  console.error(`Error: File not found: ${filePath}`);
  process.exit(1);
}

const content = await file.text();
const result = validateYaml(content);

if (result.valid) {
  console.log(`Valid YAML: ${filePath}`);
  process.exit(0);
} else {
  console.error(`Invalid YAML: ${filePath}`);
  for (const error of result.errors) {
    console.error(`  Line ${error.line}: ${error.message}`);
  }
  process.exit(1);
}

import { describe, expect, test } from "bun:test";
import { validateYaml, type ValidationResult } from "./yaml-validator";

describe("yaml-validator", () => {
  describe("valid YAML", () => {
    test("simple key-value mapping", () => {
      const result = validateYaml("name: Alice\nage: 30");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("nested mappings with proper indentation", () => {
      const yaml = [
        "person:",
        "  name: Alice",
        "  address:",
        "    city: Wonderland",
        "    zip: 12345",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("sequences with dash-space prefix", () => {
      const yaml = [
        "fruits:",
        "  - apple",
        "  - banana",
        "  - cherry",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("mixed mappings and sequences", () => {
      const yaml = [
        "people:",
        "  - name: Alice",
        "    age: 30",
        "  - name: Bob",
        "    age: 25",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("double-quoted strings", () => {
      const result = validateYaml('message: "Hello, World!"');
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("single-quoted strings", () => {
      const result = validateYaml("message: 'Hello, World!'");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("double-quoted string with escapes", () => {
      const result = validateYaml('message: "line1\\nline2"');
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("multi-line block scalar with literal style (|)", () => {
      const yaml = [
        "description: |",
        "  This is a long",
        "  description that spans",
        "  multiple lines.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("multi-line block scalar with folded style (>)", () => {
      const yaml = [
        "description: >",
        "  This is a long",
        "  description that will",
        "  be folded.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("block scalar with strip chomp indicator (|-)", () => {
      const yaml = [
        "text: |-",
        "  stripped trailing",
        "  newlines here",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("block scalar with keep chomp indicator (|+)", () => {
      const yaml = [
        "text: |+",
        "  keep trailing",
        "  newlines here",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("block scalar with folded-strip (>-)", () => {
      const yaml = [
        "text: >-",
        "  folded and stripped",
        "  content here",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("block scalar with folded-keep (>+)", () => {
      const yaml = [
        "text: >+",
        "  folded and kept",
        "  content here",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("full-line comments", () => {
      const yaml = [
        "# This is a comment",
        "name: Alice",
        "# Another comment",
        "age: 30",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("inline comments", () => {
      const result = validateYaml("name: Alice # a comment");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("empty content", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("whitespace-only content", () => {
      const result = validateYaml("   \n  \n   ");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("document start marker (---)", () => {
      const yaml = ["---", "name: Alice", "age: 30"].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("document end marker (...)", () => {
      const yaml = ["name: Alice", "..."].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("flow mapping", () => {
      const result = validateYaml("{key: value}");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("flow mapping with multiple entries", () => {
      const result = validateYaml("{a: 1, b: 2}");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("flow sequence", () => {
      const result = validateYaml("[1, 2, 3]");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("flow collection as mapping value", () => {
      const result = validateYaml("items: [apple, banana, cherry]");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("nested flow collection as mapping value", () => {
      const result = validateYaml("config: {debug: true, ports: [80, 443]}");
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("boolean scalar values", () => {
      const yaml = ["enabled: true", "disabled: false"].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("null scalar values", () => {
      const yaml = ["empty: null", "also_empty: ~"].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("numeric scalar values", () => {
      const yaml = [
        "integer: 42",
        "negative: -7",
        "float: 3.14",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("mapping with empty value", () => {
      const yaml = [
        "parent:",
        "  child: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("empty lines between entries", () => {
      const yaml = [
        "name: Alice",
        "",
        "age: 30",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    test("sequence item with block scalar", () => {
      const yaml = [
        "items:",
        "  - |",
        "    multi line",
        "    content",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });
  });

  describe("invalid YAML", () => {
    test("tab indentation", () => {
      const yaml = "name:\n\tvalue";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Tab");
    });

    test("tab indentation reports correct line number", () => {
      const yaml = "name: ok\n\tbad: line";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].line).toBe(2);
    });

    test("inconsistent de-indentation", () => {
      const yaml = [
        "root:",
        "    deep:",
        "      deeper: value",
        "   bad: indentation",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("de-indentation");
    });

    test("missing colon-space separator in mapping", () => {
      const result = validateYaml("key:value");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("colon");
    });

    test("unmatched double quote", () => {
      const result = validateYaml('name: "unclosed');
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("quote");
    });

    test("unmatched single quote", () => {
      const result = validateYaml("name: 'unclosed");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("quote");
    });

    test("unmatched opening brace in flow collection", () => {
      const result = validateYaml("{key: value");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("flow collection");
    });

    test("unmatched opening bracket in flow collection", () => {
      const result = validateYaml("[1, 2, 3");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("flow collection");
    });

    test("unmatched closing brace", () => {
      const result = validateYaml("key: value}");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("brace");
    });

    test("unmatched closing bracket", () => {
      const result = validateYaml("key: value]");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("bracket");
    });

    test("tab character inside block scalar content", () => {
      const yaml = [
        "text: |",
        "\tbad indentation",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Tab");
    });

    test("duplicate keys at the same level", () => {
      const yaml = [
        "name: Alice",
        "name: Bob",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0].message).toContain("Duplicate");
    });
  });

  describe("error reporting", () => {
    test("errors include line numbers", () => {
      const yaml = [
        "good: line",
        "another: good",
        "\tbad: line",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].line).toBe(3);
    });

    test("errors include descriptive messages", () => {
      const result = validateYaml("\tbad: value");
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toBeTruthy();
      expect(result.errors[0].message.length).toBeGreaterThan(5);
    });

    test("multiple errors are collected", () => {
      const yaml = [
        "\tbad1: value",
        "\tbad2: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBe(2);
      expect(result.errors[0].line).toBe(1);
      expect(result.errors[1].line).toBe(2);
    });

    test("missing colon-space error includes guidance", () => {
      const result = validateYaml("key:value");
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("key: value");
    });

    test("de-indentation error includes column info", () => {
      const yaml = [
        "root:",
        "    deep: value",
        "  bad: level",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toMatch(/column \d+/);
    });
  });
});

