/**
 * YAML syntax validator module.
 * Provides a pure-function validator that checks YAML content
 * for syntactic correctness using a line-by-line state-machine parser.
 */

/** Result of YAML validation. */
export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/** A single validation error with location and description. */
export interface ValidationError {
  line: number;
  message: string;
}

/** Internal parser state for tracking indentation context. */
interface ParserState {
  /** Stack of indentation levels. */
  indentStack: number[];
  /** Current context type at each indent level. */
  contextStack: Array<"mapping" | "sequence" | "scalar">;
  /** Whether currently inside a block scalar (| or >). */
  inBlockScalar: boolean;
  /** Expected minimum indentation for block scalar content. */
  blockScalarIndent: number;
  /** Whether block scalar indentation has been determined from first content line. */
  blockScalarDetermined: boolean;
  /** Line number (1-based). */
  lineNumber: number;
  /** Collected errors. */
  errors: ValidationError[];
  /** Nesting depth inside flow collections ({} and []). */
  flowDepth: number;
  /** Tracks keys at each indent level for duplicate detection. */
  keySets: Map<number, Set<string>>;
}

/**
 * Validate the syntax of a YAML string.
 * Returns a result indicating whether the content is valid YAML
 * and any errors found during parsing.
 */
export function validateYaml(content: string): ValidationResult {
  if (content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const lines = content.split("\n");
  const state: ParserState = {
    indentStack: [0],
    contextStack: ["mapping"],
    inBlockScalar: false,
    blockScalarIndent: 0,
    blockScalarDetermined: false,
    lineNumber: 0,
    errors: [],
    flowDepth: 0,
    keySets: new Map([[0, new Set<string>()]]),
  };

  for (const line of lines) {
    state.lineNumber++;
    processLine(line, state);
  }

  if (state.flowDepth > 0) {
    addError(state, "Unclosed flow collection (missing closing bracket or brace)");
  }

  return {
    valid: state.errors.length === 0,
    errors: state.errors,
  };
}

function addError(state: ParserState, message: string): void {
  state.errors.push({ line: state.lineNumber, message });
}

function getIndentation(line: string): number {
  const match = line.match(/^( *)/);
  return match ? match[1].length : 0;
}

function hasTabIndentation(line: string): boolean {
  const leading = line.match(/^(\s*)/);
  if (!leading) return false;
  return leading[1].includes("\t");
}

function processLine(line: string, state: ParserState): void {
  if (state.inBlockScalar) {
    if (line.trim() === "") return;

    if (hasTabIndentation(line)) {
      addError(state, "Tab character in indentation (use spaces)");
      return;
    }

    const indent = getIndentation(line);

    if (!state.blockScalarDetermined) {
      if (indent > state.blockScalarIndent) {
        state.blockScalarIndent = indent;
        state.blockScalarDetermined = true;
        return;
      }
      state.inBlockScalar = false;
      state.blockScalarDetermined = false;
    } else {
      if (indent >= state.blockScalarIndent) return;
      state.inBlockScalar = false;
      state.blockScalarDetermined = false;
    }
  }

  if (line.trim() === "") return;

  if (hasTabIndentation(line)) {
    addError(state, "Tab character in indentation (use spaces)");
    return;
  }

  const indent = getIndentation(line);
  const trimmed = line.trim();

  if (state.flowDepth > 0) {
    checkQuotes(trimmed, state);
    const { delta, unmatched } = countFlowDepthChange(trimmed);
    if (unmatched) {
      addError(state, "Unexpected closing bracket or brace in flow collection");
      state.flowDepth = 0;
    } else {
      state.flowDepth += delta;
    }
    return;
  }

  if (trimmed === "---" || trimmed === "...") {
    state.indentStack = [0];
    state.contextStack = ["mapping"];
    state.keySets = new Map([[0, new Set<string>()]]);
    return;
  }

  if (trimmed.startsWith("#")) {
    return;
  }

  checkQuotes(trimmed, state);
  manageIndentation(indent, state);

  const contentAfterIndent = line.slice(indent);
  const strippedContent = stripComment(contentAfterIndent);

  if (contentAfterIndent.startsWith("- ") || strippedContent === "-") {
    handleSequenceItem(indent, contentAfterIndent, state);
    return;
  }

  const sepIdx = findMappingSeparator(contentAfterIndent);
  if (sepIdx >= 0) {
    handleMappingEntry(indent, contentAfterIndent, sepIdx, state);
    return;
  }

  if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
    const { delta, unmatched } = countFlowDepthChange(trimmed);
    if (unmatched) {
      addError(state, "Unexpected closing bracket or brace");
    } else {
      state.flowDepth += delta;
    }
    return;
  }

  if (hasSuspiciousColon(contentAfterIndent)) {
    addError(state, "Missing space after colon in mapping (expected 'key: value')");
    return;
  }
}

function handleSequenceItem(
  indent: number,
  contentAfterIndent: string,
  state: ParserState,
): void {
  const ctxIdx = state.indentStack.indexOf(indent);
  if (ctxIdx >= 0 && ctxIdx < state.contextStack.length) {
    state.contextStack[ctxIdx] = "sequence";
  }

  if (!contentAfterIndent.startsWith("- ")) return;

  const itemContent = contentAfterIndent.slice(2);
  const trimmedItem = itemContent.trim();
  if (trimmedItem === "") return;

  const strippedItem = stripComment(trimmedItem);

  if (isBlockScalarIndicator(strippedItem)) {
    state.inBlockScalar = true;
    state.blockScalarIndent = indent + 2;
    state.blockScalarDetermined = false;
    return;
  }

  const { delta, unmatched } = countFlowDepthChange(itemContent);
  if (unmatched) {
    addError(state, "Unexpected closing bracket or brace");
  } else {
    state.flowDepth += delta;
  }
}

function handleMappingEntry(
  indent: number,
  contentAfterIndent: string,
  sepIdx: number,
  state: ParserState,
): void {
  const ctxIdx = state.indentStack.indexOf(indent);
  if (ctxIdx >= 0 && ctxIdx < state.contextStack.length) {
    state.contextStack[ctxIdx] = "mapping";
  }

  const key = contentAfterIndent.slice(0, sepIdx).trim();
  const value = contentAfterIndent.slice(sepIdx + 1).trim();
  const strippedValue = stripComment(value);

  const keySet = state.keySets.get(indent);
  if (keySet) {
    const normalizedKey = key.replace(/^['"](.*)['"]$/, "$1");
    if (keySet.has(normalizedKey)) {
      addError(state, `Duplicate key "${normalizedKey}"`);
    } else {
      keySet.add(normalizedKey);
    }
  }

  if (strippedValue === "") return;

  if (isBlockScalarIndicator(strippedValue)) {
    state.inBlockScalar = true;
    state.blockScalarIndent = indent + 1;
    state.blockScalarDetermined = false;
    return;
  }

  const { delta, unmatched } = countFlowDepthChange(strippedValue);
  if (unmatched) {
    addError(state, "Unexpected closing bracket or brace");
  } else {
    state.flowDepth += delta;
  }
}

function manageIndentation(indent: number, state: ParserState): void {
  const currentIndent = state.indentStack[state.indentStack.length - 1];

  if (indent > currentIndent) {
    state.indentStack.push(indent);
    state.contextStack.push("mapping");
    state.keySets.set(indent, new Set<string>());
    return;
  }

  if (indent < currentIndent) {
    while (
      state.indentStack.length > 1 &&
      state.indentStack[state.indentStack.length - 1] > indent
    ) {
      const popped = state.indentStack.pop()!;
      state.contextStack.pop();
      state.keySets.delete(popped);
    }

    if (state.indentStack[state.indentStack.length - 1] !== indent) {
      addError(
        state,
        `Invalid de-indentation to column ${indent} (not a previously established level)`,
      );
      state.indentStack.push(indent);
      state.contextStack.push("mapping");
      state.keySets.set(indent, new Set<string>());
    }
  }
}

function findMappingSeparator(content: string): number {
  let inDouble = false;
  let inSingle = false;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];

    if (inDouble) {
      if (ch === "\\" && i + 1 < content.length) {
        i++;
        continue;
      }
      if (ch === '"') inDouble = false;
      continue;
    }

    if (inSingle) {
      if (ch === "'" && i + 1 < content.length && content[i + 1] === "'") {
        i++;
        continue;
      }
      if (ch === "'") inSingle = false;
      continue;
    }

    if (ch === '"') {
      inDouble = true;
      continue;
    }
    if (ch === "'") {
      inSingle = true;
      continue;
    }

    if (ch === "#" && i > 0 && content[i - 1] === " ") break;

    if (ch === ":") {
      if (i === content.length - 1 || content[i + 1] === " ") {
        return i;
      }
    }
  }

  return -1;
}

function stripComment(content: string): string {
  let inDouble = false;
  let inSingle = false;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];

    if (inDouble) {
      if (ch === "\\" && i + 1 < content.length) {
        i++;
        continue;
      }
      if (ch === '"') inDouble = false;
      continue;
    }

    if (inSingle) {
      if (ch === "'" && i + 1 < content.length && content[i + 1] === "'") {
        i++;
        continue;
      }
      if (ch === "'") inSingle = false;
      continue;
    }

    if (ch === '"') {
      inDouble = true;
      continue;
    }
    if (ch === "'") {
      inSingle = true;
      continue;
    }

    if (ch === "#" && i > 0 && content[i - 1] === " ") {
      return content.slice(0, i - 1).trimEnd();
    }
  }

  return content;
}

function checkQuotes(content: string, state: ParserState): void {
  let i = 0;
  while (i < content.length) {
    if (content[i] === "#" && i > 0 && content[i - 1] === " ") {
      return;
    }

    if (content[i] === '"') {
      i++;
      while (i < content.length) {
        if (content[i] === "\\" && i + 1 < content.length) {
          i += 2;
          continue;
        }
        if (content[i] === '"') break;
        i++;
      }
      if (i >= content.length) {
        addError(state, "Unmatched double quote");
        return;
      }
      i++;
    } else if (content[i] === "'") {
      i++;
      while (i < content.length) {
        if (
          content[i] === "'" &&
          i + 1 < content.length &&
          content[i + 1] === "'"
        ) {
          i += 2;
          continue;
        }
        if (content[i] === "'") break;
        i++;
      }
      if (i >= content.length) {
        addError(state, "Unmatched single quote");
        return;
      }
      i++;
    } else {
      i++;
    }
  }
}

function countFlowDepthChange(content: string): {
  delta: number;
  unmatched: boolean;
} {
  let depth = 0;
  let inDouble = false;
  let inSingle = false;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];

    if (inDouble) {
      if (ch === "\\" && i + 1 < content.length) {
        i++;
        continue;
      }
      if (ch === '"') inDouble = false;
      continue;
    }

    if (inSingle) {
      if (ch === "'" && i + 1 < content.length && content[i + 1] === "'") {
        i++;
        continue;
      }
      if (ch === "'") inSingle = false;
      continue;
    }

    if (ch === '"') {
      inDouble = true;
      continue;
    }
    if (ch === "'") {
      inSingle = true;
      continue;
    }

    if (ch === "#" && i > 0 && content[i - 1] === " ") break;

    if (ch === "{" || ch === "[") depth++;
    if (ch === "}" || ch === "]") {
      depth--;
      if (depth < 0) return { delta: depth, unmatched: true };
    }
  }

  return { delta: depth, unmatched: false };
}

function isBlockScalarIndicator(value: string): boolean {
  const trimmed = value.trim();
  return /^[|>][+-]?\s*(#.*)?$/.test(trimmed);
}

function hasSuspiciousColon(content: string): boolean {
  let inDouble = false;
  let inSingle = false;

  for (let i = 0; i < content.length; i++) {
    const ch = content[i];

    if (inDouble) {
      if (ch === "\\" && i + 1 < content.length) {
        i++;
        continue;
      }
      if (ch === '"') inDouble = false;
      continue;
    }

    if (inSingle) {
      if (ch === "'" && i + 1 < content.length && content[i + 1] === "'") {
        i++;
        continue;
      }
      if (ch === "'") inSingle = false;
      continue;
    }

    if (ch === '"') {
      inDouble = true;
      continue;
    }
    if (ch === "'") {
      inSingle = true;
      continue;
    }

    if (ch === "#" && i > 0 && content[i - 1] === " ") return false;

    if (ch === ":" && i > 0 && i < content.length - 1) {
      const after = content[i + 1];
      if (after === "/" && i + 2 < content.length && content[i + 2] === "/") {
        continue;
      }
      if (/\w/.test(content[i - 1]) && /\S/.test(after) && after !== " ") {
        return true;
      }
    }
  }

  return false;
}

