  ['quoted strings', 'key: \"hello world\"'],
  ['single quotes', \"key: 'hello world'\"],
  ['block scalar', 'data: |\n  line1\n  line2'],
  ['comments', '# This is a comment\nkey: value # inline'],
  ['empty', ''],
  ['doc marker', '---\nkey: value'],
  ['flow map', '{key: value}'],
  ['flow seq', '[a, b, c]'],
  ['null value', 'key: null'],
  ['boolean', 'key: true'],
  ['number', 'key: 42'],

  // Invalid cases
  ['tab indent', '\tkey: value'],
  ['unmatched quote', 'key: \"unclosed'],
  ['unmatched brace', 'key: {unclosed'],
  ['duplicate key', 'key: val1\nkey: val2'],
